{"implementation": "def solve(case):
    segments = case.get('segments')
    if not segments:
        raise ValueError('missing segments')
    budget = case.get('budget')
    if budget is None:
        raise ValueError('missing budget')
    total_min = 0
    total_cap = 0
    for seg in segments:
        if not all(k in seg for k in ('name','importance','minimum','capacity')):
            raise ValueError('segment missing fields')
        total_min += seg['minimum']
        total_cap += seg['capacity']
    if budget < total_min:
        raise ValueError('budget below total minimum')
    if budget > total_cap:
        raise ValueError('budget exceeds total capacity')
    alloc = [seg['minimum'] for seg in segments]
    total = total_min
    while total < budget:
        best_idx = -1
        best_num = 0
        best_den = 1
        for i, seg in enumerate(segments):
            if alloc[i] >= seg['capacity']:
                continue
            num = seg['importance']
            den = alloc[i] + 1
            if best_idx == -1 or num * best_den > best_num * den:
                best_idx = i
                best_num = num
                best_den = den
        alloc[best_idx] += 1
        total += 1
    by_name = {seg['name']: alloc[i] for i, seg in enumerate(segments)}
    return {
        'allocations': alloc,
        'by_name': by_name,
        'total': total
    }"}
